	private static RootIntersectionResult merge(LmdbAdjacencyRootDomainCursor outer,
			LmdbAdjacencyRootDomainCursor exists) {
		boolean hasOuter = outer.advance();
		boolean hasExists = exists.advance();
		long rootsVisited = (hasOuter ? 1L : 0L) + (hasExists ? 1L : 0L);
		long count = 0L;
		while (hasOuter && hasExists) {
			int comparison = Long.compareUnsigned(outer.root(), exists.root());
			if (comparison == 0) {
				count++;
				hasOuter = outer.advance();
				hasExists = exists.advance();
				rootsVisited += (hasOuter ? 1L : 0L) + (hasExists ? 1L : 0L);
			} else if (comparison < 0) {
				hasOuter = outer.advance();
				rootsVisited += hasOuter ? 1L : 0L;
			} else {
				hasExists = exists.advance();
				rootsVisited += hasExists ? 1L : 0L;
			}
		}
		return new RootIntersectionResult(count, rootsVisited);
	}

	private static void closeAll(NativeLmdbQuerySource.ParallelSource[] sources) {
		if (sources == null) {
			return;
		}
		Throwable failure = null;
		for (NativeLmdbQuerySource.ParallelSource source : sources) {
			if (source == null) {
				continue;
			}
			try {
				source.close();
			} catch (RuntimeException | Error problem) {
				if (failure == null) {
					failure = problem;
				} else if (failure != problem) {
					failure.addSuppressed(problem);
				}
			}
		}
		if (failure instanceof Error) {
			throw (Error) failure;
		}
		if (failure != null) {
			throw (RuntimeException) failure;
		}
	}

